<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['student_id']??0);$lrn=trim($_POST['lrn']??'');$first=trim($_POST['firstname']??'');$middle=trim($_POST['middle_name']??'');$last=trim($_POST['lastname']??'');$suffix=trim($_POST['suffix']??'');$status=($_POST['record_status']??'active')==='inactive'?'inactive':'active';if(!preg_match('/^[0-9]{12}$/',$lrn)||$first===''||$last===''){flash('LRN must be 12 digits; first and last names are required.','error');}else{try{if($id){$q=$conn->prepare('UPDATE students SET lrn=?,firstname=?,middle_name=?,lastname=?,suffix=?,record_status=? WHERE student_id=?');$q->bind_param('ssssssi',$lrn,$first,$middle,$last,$suffix,$status,$id);$q->execute();audit($conn,$_SESSION['user_id'],'student_updated','student',$id);}else{$q=$conn->prepare('INSERT INTO students(lrn,firstname,middle_name,lastname,suffix,record_status) VALUES(?,?,?,?,?,?)');$q->bind_param('ssssss',$lrn,$first,$middle,$last,$suffix,$status);$q->execute();audit($conn,$_SESSION['user_id'],'student_created','student',(int)$conn->insert_id);}flash('Student record saved.');}catch(mysqli_sql_exception $ex){flash('Could not save. Check that the LRN is not already used.','error');}}go('/spi/admin/students.php');}
$edit=null;if(isset($_GET['edit'])){$q=$conn->prepare('SELECT * FROM students WHERE student_id=?');$q->bind_param('i',$_GET['edit']);$q->execute();$edit=$q->get_result()->fetch_assoc();}$search=trim($_GET['q']??'');$like='%'.$search.'%';$q=$conn->prepare('SELECT * FROM students WHERE lrn LIKE ? OR firstname LIKE ? OR middle_name LIKE ? OR lastname LIKE ? ORDER BY lastname,firstname LIMIT 250');$q->bind_param('ssss',$like,$like,$like,$like);$q->execute();$rows=$q->get_result();
page_start('Students');echo '<h1>Student records</h1><section class="card"><h2>'.($edit?'Edit':'Add').' official record</h2><form method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="student_id" value="'.(int)($edit['student_id']??0).'"><div class="formgrid">';foreach(['lrn'=>'LRN (12 digits)','firstname'=>'First name','middle_name'=>'Middle name','lastname'=>'Last name','suffix'=>'Suffix'] as $k=>$label)echo '<label>'.e($label).'<input name="'.e($k).'" value="'.e($edit[$k]??'').'" '.($k==='lrn'||$k==='firstname'||$k==='lastname'?'required':'').'></label>';echo '<label>Record status<select name="record_status"><option>active</option><option '.(($edit['record_status']??'')==='inactive'?'selected':'').'>inactive</option></select></label></div><button>Save student</button></form></section><form class="search"><label>Search LRN or name<input name="q" value="'.e($search).'"></label><button>Search</button></form><div class="tablewrap"><table><thead><tr><th>LRN</th><th>Student</th><th>Status</th><th>Action</th></tr></thead><tbody>';while($s=$rows->fetch_assoc())echo '<tr><td>'.e($s['lrn']).'</td><td>'.e(trim($s['firstname'].' '.$s['middle_name'].' '.$s['lastname'].' '.$s['suffix'])).'</td><td>'.e($s['record_status']).'</td><td><a href="?edit='.(int)$s['student_id'].'">Edit</a></td></tr>';echo '</tbody></table></div>';page_end();
